INSERT OR IGNORE INTO posts (slug,title,description,cover,body,status,published_at,updated_at,author) VALUES ('how-to-improve-cibil-score','How to Improve Your CIBIL Score: 8 Steps That Actually Work','A practical guide to raising your CIBIL score — from paying on time to managing utilisation and disputing errors.','/img/credit-card.webp','<p>Your CIBIL score is a three-digit number between 300 and 900 that lenders use to judge how reliably you repay. A score above 750 typically unlocks faster approvals and lower interest rates. The good news: it can be improved with consistent habits.</p> <h2>1. Pay every EMI and card bill on time</h2><p>Payment history is the single largest factor in your score. Set up auto-debit for at least the minimum amount due so a busy month never turns into a missed payment.</p> <h2>2. Keep credit utilisation below 30%</h2><p>If your card limit is ₹1,00,000, try to keep the outstanding balance under ₹30,000. High utilisation signals credit hunger, even if you pay in full.</p> <h2>3. Don''t close your oldest card</h2><p>A long credit history helps. Keep older, fee-free cards active with a small monthly spend.</p> <h2>4. Space out new loan applications</h2><p>Every application creates a hard enquiry. Several within a few months can pull your score down — check eligibility first.</p> <h2>5. Maintain a healthy credit mix</h2><p>A balance of secured loans (home, car, gold) and unsecured credit (cards, personal loans) shows you can handle different kinds of credit.</p> <h2>6. Check your report for errors</h2><p>Download your free report at least once a year. Raise a dispute with the bureau for any loan you don''t recognise or a payment wrongly marked late.</p> <h2>7. Settle, don''t ignore, overdue accounts</h2><p>Clear overdue amounts in full where possible. A ''settled'' status is better than an open default, but ''closed'' is better still.</p> <h2>8. Be patient</h2><p>Positive changes usually show up within 30 to 90 days as lenders report fresh data to the bureaus.</p> <div class="callout"><strong>Tip:</strong> Checking your own score is a soft enquiry and never affects it. <a href="/credit-score/">Check yours free with Credsey</a>.</div>','published','2026-10-10T09:00:00Z','2026-10-10T09:00:00Z','Credsey team');
INSERT OR IGNORE INTO posts (slug,title,description,cover,body,status,published_at,updated_at,author) VALUES ('personal-loan-vs-credit-card','Personal Loan vs Credit Card: Which Is Cheaper for Big Expenses?','Comparing interest, flexibility and costs to help you choose between a personal loan and a credit card for large purchases.','/img/personal-loan.webp','<p>When a large expense comes up — a wedding, a medical bill or a home renovation — the two quickest options are usually a personal loan or your credit card. They work very differently, and the wrong choice can cost you thousands.</p> <h2>Interest rates</h2><p>Credit card revolving interest runs at roughly 36–45% a year. Personal loans typically range from 10.5% to 24%. For anything you can''t repay within the interest-free period, a personal loan is almost always cheaper.</p> <h2>When a credit card wins</h2><ul><li>You can repay the full amount within the 45–50 day interest-free period.</li><li>The purchase qualifies for a no-cost EMI offer.</li><li>You need a small amount for a short time.</li></ul> <h2>When a personal loan wins</h2><ul><li>The amount is large and repayment will take more than a few months.</li><li>You want a fixed EMI and a clear end date.</li><li>You''re consolidating several high-interest card balances.</li></ul> <h2>Example</h2><p>₹2,00,000 repaid over 24 months: at 12% on a personal loan the EMI is about ₹9,415, with total interest of around ₹26,000. Revolving the same amount on a card at 42% can cost more than ₹90,000 in interest.</p> <div class="callout">Run your own numbers with the <a href="/emi-calculator/">Credsey EMI calculator</a>.</div>','published','2026-10-03T09:00:00Z','2026-10-03T09:00:00Z','Credsey team');
INSERT OR IGNORE INTO posts (slug,title,description,cover,body,status,published_at,updated_at,author) VALUES ('home-loan-documents-checklist','Home Loan Documents Checklist for Salaried & Self-Employed','The complete list of KYC, income and property documents you need for a home loan in India — so your application moves without delays.','/img/home-model.webp','<p>Most home loan delays come from missing paperwork. Keep this checklist handy and your file will move from login to sanction much faster.</p> <h2>For everyone</h2><ul><li>Completed application form with photographs</li><li>PAN card (mandatory)</li><li>Aadhaar, passport or voter ID for address proof</li><li>6 months'' bank statements of the salary or main business account</li></ul> <h2>Salaried applicants</h2><ul><li>Last 3 months'' salary slips</li><li>Form 16 for the last 2 years</li><li>Employment letter if you''ve been in the job less than a year</li></ul> <h2>Self-employed applicants</h2><ul><li>ITR with computation of income for the last 2–3 years</li><li>Audited balance sheet and profit & loss statement</li><li>Business registration proof: GST, Udyam or shop licence</li></ul> <h2>Property documents</h2><ul><li>Allotment letter or agreement for sale</li><li>Title deed chain and encumbrance certificate</li><li>Approved building plan and NOC from the society or builder</li><li>Receipts of payments made to the builder or seller</li></ul> <div class="callout">Credsey advisors check your file before it reaches the lender, so nothing goes back and forth. <a href="/apply/?product=home">Start your home loan application</a>.</div>','published','2026-09-26T09:00:00Z','2026-09-26T09:00:00Z','Credsey team');
